+      font-weight: 700;
+      transition: transform 180ms ease, background-color 180ms ease;
+    }
+
+    .question[aria-expanded="true"] .icon {
+      transform: rotate(45deg);
+      background: #dbeafe;
+    }
+
+    .details {
+      border-top: 1px solid var(--border);
+      padding: 0 24px 22px;
+      color: var(--muted);
+      line-height: 1.75;
+      font-size: 0.98rem;
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      margin: 16px 0 0;
+    }
+
