 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Cat FAQ</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f5f7fb;
       --surface: rgba(255, 255, 255, 0.9);
       --surface-strong: #ffffff;
       --text: #1f2937;
       --muted: #6b7280;
       --border: #e5e7eb;
       --accent: #2563eb;
       --accent-soft: #dbeafe;
       --shadow: 0 20px 50px rgba(15, 23, 42, 0.08);
       --radius: 20px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, #e0f2fe 0, transparent 35%),
         linear-gradient(180deg, #f8fafc 0%, var(--bg) 100%);
       color: var(--text);
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 32px 16px;
     }

     .page {
       width: min(920px, 100%);
       background: var(--surface);
       border: 1px solid rgba(229, 231, 235, 0.8);
       border-radius: calc(var(--radius) + 6px);
       box-shadow: var(--shadow);
       backdrop-filter: blur(12px);
       overflow: hidden;
     }

     .hero {
       padding: 40px 40px 24px;
       background: linear-gradient(135deg, #ffffff 0%, #f8fbff 100%);
       border-bottom: 1px solid var(--border);
     }

     .eyebrow {
       margin: 0 0 12px;
       font-size: 0.78rem;
       font-weight: 700;
       letter-spacing: 0.12em;
       text-transform: uppercase;
       color: var(--accent);
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.25rem);
       line-height: 1.05;
     }

     .subtitle {
       margin: 14px 0 0;
       max-width: 60ch;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.7;
     }

     .faq {
       padding: 24px;
     }

     .example {
       border: 1px solid var(--border);
       border-radius: 18px;
       background: var(--surface-strong);
       margin: 0 0 16px;
       overflow: hidden;
       transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease;
     }

     .example:hover {
       border-color: #cbd5e1;
       box-shadow: 0 12px 30px rgba(15, 23, 42, 0.06);
       transform: translateY(-1px);
     }

     .question {
       width: 100%;
       border: 0;
       background: transparent;
       color: inherit;
       font: inherit;
       text-align: left;
       padding: 22px 24px;
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 16px;
       cursor: pointer;
     }

     .question:focus-visible {
       outline: 3px solid var(--accent-soft);
       outline-offset: -3px;
     }

     .question-text {
       margin: 0;
       font-size: 1.04rem;
       font-weight: 650;
       line-height: 1.4;
     }

     .icon {
       flex: 0 0 auto;
       width: 38px;
       height: 38px;
       border-radius: 999px;
       display: grid;
       place-items: center;
       background: var(--accent-soft);
       color: var(--accent);
       font-size: 1.4rem;
       font-weight: 700;
       transition: transform 180ms ease, background-color 180ms ease;
     }

     .question[aria-expanded="true"] .icon {
       transform: rotate(45deg);
       background: #dbeafe;
     }

     .details {
       border-top: 1px solid var(--border);
       padding: 0 24px 22px;
       color: var(--muted);
       line-height: 1.75;
       font-size: 0.98rem;
     }

     .details[hidden] {
       display: none;
